// LCD'de sıcaklık ve nem: DHT22 ölçer, 16x2 LCD (4 bit kipi) gösterir.
#include <LiquidCrystal.h>
#include <DHT.h>

const int DHT_PIN = 7;
const int LCD_RS = 12;
const int LCD_E = 11;
const int LCD_D4 = 5;
const int LCD_D5 = 4;
const int LCD_D6 = 3;
const int LCD_D7 = 2;
const unsigned long OLCUM_ARALIGI = 2000; // ms; DHT22 en hızlı 2 sn'de bir ölçer.

LiquidCrystal lcd(LCD_RS, LCD_E, LCD_D4, LCD_D5, LCD_D6, LCD_D7);
DHT dht(DHT_PIN, DHT22);

// LCD'de derece işareti yok; 5x8 piksellik kendi karakterimizi çizeriz.
byte derece[8] = {0b00110, 0b01001, 0b01001, 0b00110, 0, 0, 0, 0};

void setup() {
  Serial.begin(9600);
  dht.begin();
  lcd.begin(16, 2);
  lcd.createChar(0, derece);
  lcd.print("Olculuyor...");
}

void loop() {
  delay(OLCUM_ARALIGI);
  float sicaklik = dht.readTemperature();
  float nem = dht.readHumidity();

  lcd.clear();
  if (isnan(sicaklik) || isnan(nem)) {
    lcd.print("Sensor hatasi");
    lcd.setCursor(0, 1);
    lcd.print("Kablo kontrol et");
    Serial.println("DHT22 okunamadi");
    return;
  }

  // Üst satır: sıcaklık.
  lcd.print("Sicaklik: ");
  lcd.print(sicaklik, 1);
  lcd.write(byte(0));
  lcd.print("C");
  // Alt satır: nem.
  lcd.setCursor(0, 1);
  lcd.print("Nem:      ");
  lcd.print(nem, 1);
  lcd.print("%");

  Serial.print("Sicaklik: ");
  Serial.print(sicaklik, 1);
  Serial.print(" C  Nem: ");
  Serial.print(nem, 1);
  Serial.println(" %");
}
